WITH src AS (SELECT * FROM stores WHERE store_name LIKE '%Central%'), Summary AS (SELECT CASE WHEN sqft >= 14852 THEN 'high' WHEN sqft >= 7174 THEN 'mid' ELSE 'low' END AS sqft_bucket, YEAR(opened_date) AS opened_year, SUM(sqft) AS total_sqft, MAX(sqft) AS max_sqft FROM src GROUP BY CASE WHEN sqft >= 14852 THEN 'high' WHEN sqft >= 7174 THEN 'mid' ELSE 'low' END, YEAR(opened_date)) SELECT sqft_bucket, opened_year, total_sqft FROM Summary ORDER BY total_sqft DESC, sqft_bucket, opened_year LIMIT 3;
